head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > M > getOpenPanelInfo]<br/>Accordion 컴포넌트에서 열려 있는 패널 중 특정 인덱스에 해당하는 패널의 정보를 객체로 반환합니다.",
    "validation" : [
        "index(선택) 파라미터로 지정한 열린 패널 인덱스(0부터 시작)에 해당하는 패널 정보 객체를 반환합니다.",
        "index(선택) 파라미터를 생략하면 기본값 0 으로 적용되어 첫 번째 열린 패널 정보 객체를 반환합니다.",
        "index(선택) 파라미터에 null 을 전달하면 기본값 0 으로 적용되어 첫 번째 열린 패널 정보 객체를 반환합니다.",
        "index 파라미터값이 열려 있는 패널 수 이상이면 빈 배열([]) 을 반환합니다.",
        "반환된 객체의 result.id 는 패널의 렌더링 ID (String) 를 갖습니다.",
        "반환된 객체의 result.org_id 는 패널이 컴포넌트 내에서 부여된 ID (String) 를 갖습니다.",
        "반환된 객체의 result.userID 는 패널의 사용자 지정 ID (String) 를 갖습니다.",
        "반환된 객체의 result.isOpen 은 패널의 열림 상태 (Boolean) 를 갖습니다.",
        "반환된 객체의 result.disabledPanels 는 패널의 비활성화 상태 (Boolean) 를 갖습니다.",
        "반환된 객체의 result.element 는 패널의 DOM Element 를 갖습니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (unCollapseAll=true 로 비-disabled 모든 패널을 초기에 열어 getOpenPanelInfo 동작 검증 환경 보장)
    let properties = {
        unCollapseAll : "true",
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* unCollapseAll=true 로 비-disabled 패널(panels1, panels2)을 초기에 열어두고, panels3 은 disabledPanels=true 로 닫힘 상태"', '', 'label1');
    $c.gcm.createLabel('label="* getOpenPanelInfo(index) → 열린 패널 목록에서 index(0부터) 의 패널 정보 객체 반환 (id / org_id / userID / isOpen / disabledPanels / element)"', '', 'label2');
    $c.gcm.createLabel('label="* par_index 입력값: 빈값 → 파라미터 생략, null 문자열 입력 → null 전달 (기본값 0 으로 적용)"', '', 'label3');
    $c.gcm.createLabel('label="* index 가 열린 패널 수 이상(예: 99) 이면 빈 배열([]) 반환"', '', 'label4');
    $c.gcm.createLabel('label="* panels2 는 userID=myUser2 로 사용자 지정 ID 가 부여됨 (result.userID 검증용)"', '', 'label5');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="myUser2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2 (userID=myUser2)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// getOpenPanelInfo(par_index) 호출 — 열린 패널 목록의 par_index 위치 패널 정보 반환
// 빈값 → 파라미터 생략, "null" → null 전달, 그 외 → Number 변환 후 전달
scwin.btn_getOpenPanelInfo_onclick = function (e) {
    let rawValue = par_index.getValue();
    let result;
    let callExpr;

    if (rawValue === "" || rawValue === undefined || rawValue === null) {
        // 파라미터 생략 → 기본값 0 적용
        callExpr = "getOpenPanelInfo()";
        result = target1.getOpenPanelInfo();
    } else if (rawValue === "null") {
        // null 전달 → 기본값 0 적용
        callExpr = "getOpenPanelInfo(null)";
        result = target1.getOpenPanelInfo(null);
    } else {
        let numValue = Number(rawValue);
        callExpr = "getOpenPanelInfo(" + numValue + ")";
        result = target1.getOpenPanelInfo(numValue);
    }

    wf_body_bottom.getObj("scwin").setReturnValue("===== " + callExpr + " 호출 =====");

    if (Array.isArray(result) && result.length === 0) {
        // index 가 열린 패널 수 이상인 경우 빈 배열 반환
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : 빈 배열 [] (index 가 열린 패널 수 이상)");
    } else if (result && typeof result === "object") {
        wf_body_bottom.getObj("scwin").setReturnValue("result.id : " + result.id);
        wf_body_bottom.getObj("scwin").setReturnValue("result.org_id : " + result.org_id);
        wf_body_bottom.getObj("scwin").setReturnValue("result.userID : " + result.userID);
        wf_body_bottom.getObj("scwin").setReturnValue("result.isOpen : " + result.isOpen);
        wf_body_bottom.getObj("scwin").setReturnValue("result.disabledPanels : " + result.disabledPanels);
        wf_body_bottom.getObj("scwin").setReturnValue("result.element.tagName : " + (result.element ? (typeof result.element.getTagName === "function" ? result.element.getTagName() : result.element.tagName) : "(element 없음)"));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : " + result);
    }
};



// 열린 패널 전체 정보 출력 (getOpenPanelListInfo) — getOpenPanelInfo 와의 차이(전체 배열 vs 특정 인덱스 객체) 검증
scwin.btn_getOpenPanelList_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id + " / userID : " + openList[i].userID);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
